  void AdvancedAction(int id){if(id==30){ToggleDesktop();return;}if(id==99){if(surface!=null&&pendingRun!=null){var run=pendingRun;pendingRun=null;run(surface);}return;}if(surface==null){pendingAdvanced=id;CaptureScreen();return;}if(id==28){using(var browser=new PageBrowser(surface))browser.ShowDialog(this);}else if(id==29){surface.ShowInk=!surface.ShowInk;surface.Invalidate();}else{chosenTool=ToolCatalog.For(id);surface.Selected=chosenTool;surface.Invalidate();surface.Activate();}Invalidate();}
