  Surface surface;ListView list=new ListView();ImageList thumbnails=new ImageList();List<Bitmap> retainedThumbnails=new List<Bitmap>();
  public PageBrowser(Surface source){surface=source;Text="ScreenInk · Páginas";ClientSize=new Size(700,490);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);BackColor=Color.FromArgb(249,250,252);thumbnails.ImageSize=new Size(140,90);thumbnails.ColorDepth=ColorDepth.Depth32Bit;list.Bounds=new Rectangle(18,18,664,352);list.View=View.LargeIcon;list.MultiSelect=false;list.LargeImageList=thumbnails;list.DoubleClick+=(o,e)=>{if(list.SelectedIndices.Count>0){surface.SwitchPage(list.SelectedIndices[0]);DialogResult=DialogResult.OK;}};Controls.Add(list);string[] titles={"Abrir","Duplicar","Excluir","Novo branco","Novo preto","Nova captura","PDF","PNGs","Fechar"};for(int i=0;i<titles.Length;i++){int id=i;var button=new Button{Text=titles[i],Bounds=new Rectangle(18+(i%5)*132,385+(i/5)*44,122,34)};button.Click+=(o,e)=>Action(id);Controls.Add(button);}Reload();}
  protected override void Dispose(bool disposing){if(disposing){thumbnails.Dispose();foreach(var image in retainedThumbnails)image.Dispose();}base.Dispose(disposing);}
  void Reload(){surface.SyncPage();list.Items.Clear();thumbnails.Images.Clear();foreach(var retained in retainedThumbnails)retained.Dispose();retainedThumbnails.Clear();for(int i=0;i<surface.Pages.Count;i++){using(var b=surface.Pages[i].Render())using(var thumb=new Bitmap(140,90))using(var g=Graphics.FromImage(thumb)){g.Clear(Color.White);g.DrawImage(b,0,0,140,90);var retained=(Bitmap)thumb.Clone();retainedThumbnails.Add(retained);thumbnails.Images.Add(retained);}list.Items.Add(new ListViewItem((i+1)+" · "+surface.Pages[i].Name,i));}list.Items[surface.PageIndex].Selected=true;}
  void Action(int id){int index=list.SelectedIndices.Count>0?list.SelectedIndices[0]:surface.PageIndex;if(id==0){surface.SwitchPage(index);DialogResult=DialogResult.OK;}else if(id==1){surface.SwitchPage(index);surface.DuplicatePage();Reload();}else if(id==2){surface.SwitchPage(index);surface.DeletePage();Reload();}else if(id==3){surface.BlankPage(Color.White);Reload();}else if(id==4){surface.BlankPage(Color.Black);Reload();}else if(id==5){DialogResult=DialogResult.OK;surface.CaptureNewPage();}else if(id==6)surface.ExportPdf();else if(id==7)surface.ExportImages();else DialogResult=DialogResult.OK;}
 }
 public class MarkRecord {
  public int Tool,Argb,FillArgb,Alpha,ArrowEnds,Dash;public float Width,TextSize;public string Text,FontFamily;public bool Bold;public ShapeKind Shape;public List<PointF> Points=new List<PointF>();
  internal static MarkRecord From(Mark m){return new MarkRecord{Tool=(int)m.Tool,Argb=m.Color.ToArgb(),FillArgb=m.Fill.ToArgb(),Alpha=m.Alpha,ArrowEnds=m.ArrowEnds,Dash=(int)m.Dash,Width=m.Width,TextSize=m.TextSize,Text=m.Text,FontFamily=m.FontFamily,Bold=m.Bold,Shape=m.Shape,Points=new List<PointF>(m.Points)};}
  internal Mark ToMark(){if(Tool<0||Tool>(int)PointofixModern.Tool.Select||Points==null||Points.Count>200000||Points.Any(p=>float.IsNaN(p.X)||float.IsNaN(p.Y)||float.IsInfinity(p.X)||float.IsInfinity(p.Y)))throw new InvalidDataException("Anotação inválida.");return new Mark{Tool=(Tool)Tool,Color=Color.FromArgb(Argb),Fill=Color.FromArgb(FillArgb),Alpha=Math.Max(0,Math.Min(255,Alpha)),ArrowEnds=Math.Max(0,Math.Min(3,ArrowEnds)),Dash=(DashStyle)Math.Max(0,Math.Min(4,Dash)),Width=Math.Max(1,Math.Min(100,Width)),TextSize=Math.Max(8,Math.Min(120,TextSize)),Text=Text,FontFamily=FontFamily??"Segoe UI",Bold=Bold,Shape=Shape,Points=new List<PointF>(Points)};}
 }
