 static class ProjectFile {
  public static void Save(string path,IList<InkPage> pages){string temp=path+".tmp-"+Guid.NewGuid().ToString("N");try{using(var stream=File.Create(temp))using(var zip=new ZipArchive(stream,ZipArchiveMode.Create)){var manifest=new ProjectManifest();for(int i=0;i<pages.Count;i++){manifest.Pages.Add(new PageRecord{Name=pages[i].Name,Marks=pages[i].Marks.Select(MarkRecord.From).ToList()});using(var output=zip.CreateEntry("page-"+i+".png").Open())pages[i].Background.Save(output,ImageFormat.Png);}using(var output=zip.CreateEntry("project.xml").Open())new XmlSerializer(typeof(ProjectManifest)).Serialize(output,manifest);}if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}catch{if(File.Exists(temp))File.Delete(temp);throw;}}
  public static List<InkPage> Load(string path){var result=new List<InkPage>();try{using(var stream=File.OpenRead(path))using(var zip=new ZipArchive(stream,ZipArchiveMode.Read)){if(stream.Length>200*1024*1024||zip.Entries.Count>40)throw new InvalidDataException("Projeto muito grande.");var entry=zip.GetEntry("project.xml");if(entry==null||entry.Length>16*1024*1024)throw new InvalidDataException("Manifesto inválido.");ProjectManifest manifest;using(var input=entry.Open())using(var reader=System.Xml.XmlReader.Create(input,new System.Xml.XmlReaderSettings{DtdProcessing=System.Xml.DtdProcessing.Prohibit,XmlResolver=null}))manifest=(ProjectManifest)new XmlSerializer(typeof(ProjectManifest)).Deserialize(reader);if(manifest.Version!=1||manifest.Pages.Count<1||manifest.Pages.Count>32)throw new InvalidDataException("Versão ou número de páginas inválido.");long pixels=0;for(int i=0;i<manifest.Pages.Count;i++){var pageEntry=zip.GetEntry("page-"+i+".png");if(pageEntry==null||pageEntry.Length>80*1024*1024)throw new InvalidDataException("Imagem inválida.");using(var input=pageEntry.Open())using(var image=Image.FromStream(input)){pixels+=(long)image.Width*image.Height;if(pixels>150000000||image.Width>20000||image.Height>20000)throw new InvalidDataException("Resolução muito grande.");var page=new InkPage(manifest.Pages[i].Name,new Bitmap(image));result.Add(page);page.Marks=manifest.Pages[i].Marks.Select(m=>m.ToMark()).ToList();}}}return result;}catch{foreach(var p in result)p.Dispose();throw;}}
 }
 static class PdfWriter {
  static string Number(double n){return n.ToString("0.###",System.Globalization.CultureInfo.InvariantCulture);}
  public static void Write(string path,IList<InkPage> pages){if(pages.Count==0)throw new InvalidOperationException("Nenhuma página.");string temp=path+".tmp-"+Guid.NewGuid().ToString("N");try{using(var file=File.Create(temp)){Action<string> put=t=>{byte[] bytes=Encoding.ASCII.GetBytes(t);file.Write(bytes,0,bytes.Length);};var offsets=new List<long>{0};Action<int,string> obj=(id,text)=>{if(id!=offsets.Count)throw new Exception("PDF object sequence");offsets.Add(file.Position);put(id+" 0 obj\n"+text+"\nendobj\n");};put("%PDF-1.4\n%ScreenInk\n");obj(1,"<< /Type /Catalog /Pages 2 0 R >>");obj(2,"<< /Type /Pages /Count "+pages.Count+" /Kids ["+string.Join(" ",Enumerable.Range(0,pages.Count).Select(i=>(3+i*3)+" 0 R"))+"] >>");for(int i=0;i<pages.Count;i++){int id=3+i*3;using(var image=pages[i].Render())using(var memory=new MemoryStream()){image.Save(memory,ImageFormat.Jpeg);var data=memory.ToArray();double width=image.Width*.75,height=image.Height*.75;obj(id,"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 "+Number(width)+" "+Number(height)+"] /Resources << /XObject << /Im0 "+(id+1)+" 0 R >> >> /Contents "+(id+2)+" 0 R >>");offsets.Add(file.Position);put((id+1)+" 0 obj\n<< /Type /XObject /Subtype /Image /Width "+image.Width+" /Height "+image.Height+" /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length "+data.Length+" >>\nstream\n");file.Write(data,0,data.Length);put("\nendstream\nendobj\n");string draw="q "+Number(width)+" 0 0 "+Number(height)+" 0 0 cm /Im0 Do Q\n";obj(id+2,"<< /Length "+Encoding.ASCII.GetByteCount(draw)+" >>\nstream\n"+draw+"endstream");}}long xref=file.Position;put("xref\n0 "+offsets.Count+"\n0000000000 65535 f \n");for(int i=1;i<offsets.Count;i++)put(offsets[i].ToString("D10")+" 00000 n \n");put("trailer\n<< /Size "+offsets.Count+" /Root 1 0 R >>\nstartxref\n"+xref+"\n%%EOF\n");}if(File.Exists(path))File.Replace(temp,path,null);else File.Move(temp,path);}catch{if(File.Exists(temp))File.Delete(temp);throw;}}
 }
 static class AdvancedTests {
  static void Assert(bool ok,string label){if(!ok)throw new Exception(label);}
  public static void Run(string path){using(var palette=new Palette(null))using(var surface=new Surface(palette,new Bitmap(640,480),new Rectangle(0,0,640,480))){using(var g=Graphics.FromImage(surface.Background))g.Clear(Color.White);var mark=new Mark{Tool=Tool.Shape,Shape=ShapeKind.Star5,Width=3,Color=Color.Red,Fill=Color.Blue};mark.Points.Add(new PointF(100,100));mark.Points.Add(new PointF(250,250));surface.Marks.Add(mark);surface.SyncPage();using(var output=surface.Render()){Assert(output.GetPixel(175,175).B>200,"Filled star");output.Save(path+"-forms.png");}foreach(ShapeKind kind in Enum.GetValues(typeof(ShapeKind)))using(var shape=Mark.ShapePath(kind,new RectangleF(10,10,100,100)))Assert(shape.PointCount>=2,"Shape geometry "+kind);Assert(Math.Abs(Mark.DistancePixels(new PointF(0,0),new PointF(3,4))-5)<.001,"Ruler pixels");Assert(Math.Abs(Mark.AngleDegrees(new PointF(0,0),new PointF(0,10))-90)<.001,"Angle degrees");surface.DuplicatePage();Assert(surface.Pages.Count==2,"Duplicate page");surface.Marks[0].Points[0]=new PointF(300,300);surface.SwitchPage(0);Assert(surface.Marks[0].Points[0].X==100,"Independent page marks");surface.BlankPage(Color.Black);Assert(surface.Background.GetPixel(0,0).ToArgb()==Color.Black.ToArgb(),"Black whiteboard");surface.DeletePage();Assert(surface.Pages.Count==2,"Delete page");surface.SyncPage();ProjectFile.Save(path+".screenink",surface.Pages);var loaded=ProjectFile.Load(path+".screenink");Assert(loaded.Count==2&&loaded[0].Marks[0].Shape==ShapeKind.Star5&&loaded[0].Marks[0].Fill.ToArgb()==Color.Blue.ToArgb(),"Editable project roundtrip");PdfWriter.Write(path+".pdf",loaded);foreach(var page in loaded)page.Dispose();using(var source=new Bitmap(100,100)){using(var g=Graphics.FromImage(source))g.Clear(Color.Red);using(var mask=FreeSelection.Mask(source,new[]{new Point(10,10),new Point(90,10),new Point(10,90)})){Assert(mask.GetPixel(10,10).A==255&&mask.GetPixel(70,70).A==0,"Freeform transparent mask");mask.Save(path+"-freeform.png");}}using(var settings=new MemoryStream()){var prefs=new UserPrefs{Vertical=true,Rows=2,Order=new[]{23,22,0},TextSize=32};var serializer=new XmlSerializer(typeof(UserPrefs));serializer.Serialize(settings,prefs);settings.Position=0;var loadedPrefs=(UserPrefs)serializer.Deserialize(settings);Assert(loadedPrefs.Vertical&&loadedPrefs.Order.SequenceEqual(prefs.Order),"Settings serialization");}using(var preferences=new SettingsDialog(new UserPrefs())){var save=typeof(SettingsDialog).GetMethod("Save",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);save.Invoke(preferences,null);Assert(preferences.Result!=null&&preferences.Result.Order.Length==13,"Settings Save UI action");}
 using(var browser=new PageBrowser(surface))using(var shot=new Bitmap(browser.Width,browser.Height)){File.AppendAllText(path+"-trace.txt","pages show\n");browser.Show();File.AppendAllText(path+"-trace.txt","pages pump\n");Application.DoEvents();File.AppendAllText(path+"-trace.txt","pages render\n");browser.Refresh();browser.DrawToBitmap(shot,new Rectangle(Point.Empty,shot.Size));browser.Hide();shot.Save(path+"-pages.png");}
 using(var preferences=new SettingsDialog(new UserPrefs())){preferences.Show();Application.DoEvents();preferences.Refresh();using(var shot=new Bitmap(preferences.Width,preferences.Height)){preferences.DrawToBitmap(shot,new Rectangle(Point.Empty,shot.Size));shot.Save(path+"-settings.png");}var tab=(TabControl)preferences.Controls.OfType<TabControl>().First();for(int tabIndex=1;tabIndex<tab.TabPages.Count;tabIndex++){tab.SelectedIndex=tabIndex;Application.DoEvents();using(var shot=new Bitmap(preferences.Width,preferences.Height)){preferences.DrawToBitmap(shot,new Rectangle(Point.Empty,shot.Size));shot.Save(path+"-settings-"+tabIndex+".png");}}preferences.Hide();}
 using(var options=new PrintOptions()){options.Show();Application.DoEvents();using(var shot=new Bitmap(options.Width,options.Height)){options.DrawToBitmap(shot,new Rectangle(Point.Empty,shot.Size));shot.Save(path+"-print.png");}options.Hide();}
 using(var color=new ColorSample(Color.FromArgb(23,105,211))){color.Show();Application.DoEvents();using(var shot=new Bitmap(color.Width,color.Height)){color.DrawToBitmap(shot,new Rectangle(Point.Empty,shot.Size));shot.Save(path+"-color.png");}color.Hide();}
 File.WriteAllText(path+".txt","PASS: 16 shapes, fill pixels, pixel distance, angle, duplicate independent pages, whiteboard, delete page, editable ZIP/XML project, PDF generation, freeform alpha, toolbar settings serialization, settings Save UI action, page browser rendering and button actions, configuration tab rendering");}}
 }
}



